/* Progressive disclosure and reuse. Does not infer missing outcomes or alter model gates. */
(function(){
'use strict';
const $=id=>document.getElementById(id),add=(p,t,text)=>{const e=document.createElement(t);e.textContent=text;p.append(e);return e;};
function moveField(id,parent){const field=$(id),label=document.querySelector('label[for="'+id+'"]');if(label)parent.append(label);parent.append(field);return field;}
const rootTimeEffects=()=>globalThis.WamTimeEffects;
const form=$('prepForm'),quick=document.createElement('section');quick.id='prepQuickStart';
add(quick,'h3','Start with the essentials');add(quick,'p','Name the decision, define success, and enter preparation time. Reuse a saved setup next time.');
const reuseLabel=add(quick,'label','Use a saved setup · optional');reuseLabel.htmlFor='prepReuse';const reuse=add(quick,'select','');reuse.id='prepReuse';
moveField('prepContext',quick);moveField('prepTask',quick);moveField('prepDefinition',quick);const time=moveField('prep_prepared_time',quick);quick.querySelector('label[for="prep_prepared_time"]').textContent='More prepared plan · planning + recovery minutes';
const assumptions=add(quick,'p','Quick comparison: no preparation versus the minutes above. It values reaching your goal at 100 and the other outcome at 0, with outcome importance 5, time importance 1 and a 60-minute major change. Spending and effort are excluded until you include them below. These are editable starting assumptions, not happiness predictions.');assumptions.className='helper';assumptions.id='prepQuickAssumptions';
const advanced=document.createElement('details');advanced.id='prepExtraSettings';const sum=add(advanced,'summary','Extra settings · costs, values, probabilities & notes');
// Keep the original input nodes and their validation/listeners intact.
for(const child of Array.from(form.children))if(child.tagName!=='BUTTON')advanced.append(child);
form.prepend(quick,advanced);const topRow=document.createElement('div');topRow.className='row';reuseLabel.before(topRow);const reuseBox=add(topRow,'div',''),categoryBox=add(topRow,'div','');reuseBox.append(reuseLabel,reuse);moveField('prepContext',categoryBox);const learningDetails=document.createElement('details');learningDetails.id='prepLearningDetails';add(learningDetails,'summary','Learning progress & probability settings');$('preparationLearning').before(learningDetails);learningDetails.append($('preparationLearning'));form.after(learningDetails);for(const key of ['time','money','effort'])$('prep_light_'+key).value='0';for(const key of ['money','effort'])$('prep_prepared_'+key).value='0';$('prepSuccess').value='100';$('prepFailure').value='0';for(const key of ['outcome','time','money','effort'])$('prepWeight_'+key).value={outcome:5,time:1,money:0,effort:0}[key];
$('prepTask').placeholder='e.g. Prepare for tomorrow’s class';$('prepDefinition').placeholder='e.g. Finish the class exercise';document.querySelector('label[for="prepDefinition"]').textContent='What would count as success?';
function refreshReuse(){const selected=reuse.value;reuse.replaceChildren(new Option('Start a new comparison',''));for(const item of saved.slice().reverse()){const s=item.preparationStudy;if(s?.version!==1||typeof s.definition!=='string')continue;reuse.add(new Option(item.task+' · '+s.definition,item.id));}if(Array.from(reuse.options).some(o=>o.value===selected))reuse.value=selected;}
function set(id,value){if(value!==undefined&&value!==null&&$(id))$(id).value=String(value);}
reuse.onchange=()=>{const item=saved.find(r=>r.id===reuse.value),s=item?.preparationStudy;if(!s)return;set('prepTask',item.task);set('prepDefinition',s.definition);set('prepContext',s.context);const x=s.input||{};for(const side of ['light','prepared'])for(const key of ['time','money','effort','low','p','high'])set('prep_'+side+'_'+key,['low','p','high'].includes(key)?'':0);for(const key of ['outcome','time','money','effort'])set('prepWeight_'+key,{outcome:5,time:1,money:0,effort:0}[key]);for(const key of ['time','money','effort'])set('prepSwing_'+key,{time:60,money:50,effort:5}[key]);$('prepDeclined').checked=x.declined===true;set('prepSuccess',x.success??100);set('prepFailure',x.failure??0);for(const side of ['light','prepared'])for(const key of ['time','money','effort','low','p','high'])set('prep_'+side+'_'+key,x[side]?.[key]);for(const key of ['outcome','time','money','effort'])set('prepWeight_'+key,x.weights?.[key]);for(const key of ['time','money','effort']){set('prepSwing_'+key,x.swings?.[key]);set('prepLimit_'+key,x.limits?.[key]??'');}set('prepBasis',s.basis||'');set('prepIfThen',s.ifThen||'');if(rootTimeEffects())rootTimeEffects().restore('prep',x.temporal);$('prepUseLearned').checked=true;$('prepUseLearned').dispatchEvent(new Event('change',{bubbles:true}));form.dispatchEvent(new Event('input',{bubbles:true}));assumptions.textContent='Reused the saved outcome, preparation and available settings; missing settings use the disclosed quick-comparison defaults. Probabilities will be recalculated from your current history. Review the minutes for this decision; extra settings remain editable.';};
advanced.addEventListener('input',()=>{assumptions.textContent='Using your current extra settings. The score includes only criteria with importance above zero; open extra settings to review values, costs and limits.';});
form.addEventListener('invalid',e=>{const details=e.target.closest('details');if(details)for(let n=details;n&&n!==form;n=n.parentElement)if(n.tagName==='DETAILS')n.open=true;},true);
const about=document.createElement('details');about.id='prepAbout';add(about,'summary','About this comparison');for(const child of Array.from($('preparation').children)){if(child===form)break;if(child.tagName==='P')about.append(child);}learningDetails.after(about);
const oldRender=render;render=function(){oldRender();refreshReuse();};document.addEventListener('wam:history-restored',refreshReuse);refreshReuse();
// Shorten the main comparison without inventing benefits or changing saved priorities.
const notes=document.createElement('details');notes.id='decisionOptionalNotes';add(notes,'summary','Add context · benefits, consequences & frequency');$('comparisonStage0').append(notes);for(const id of ['gain','skip','repeat']){moveField(id,notes);$(id).required=false;}
const simple=document.createElement('button');simple.type='button';simple.className='quiet';simple.id='simpleResourceScore';simple.textContent='Compare time & effort only';$('decisionScoreSettings').querySelector('summary').after(simple);simple.onclick=()=>{for(const n of document.querySelectorAll('[id^="decisionWeight_"]'))n.value='0';$('decisionWeight_time').value='3';$('decisionWeight_energy').value='3';$('decisionSwing_time').value='60';$('decisionSwing_energy').value='2';$('decisionScoreSettings').dispatchEvent(new Event('input',{bubbles:true}));};
const custom=document.createElement('details');custom.id='decisionCustomPriorities';add(custom,'summary','Customize priorities, limits & learned outcomes');for(const child of Array.from($('decisionScoreSettings').children))if(child.tagName!=='SUMMARY'&&child!==simple&&child.id!=='scoreReadiness'&&!child.classList.contains('preference-controls'))custom.append(child);$('decisionScoreSettings').append(custom);
const skip=document.createElement('button');skip.type='button';skip.className='quiet';skip.textContent='Skip optional benefits →';skip.onclick=()=>document.querySelectorAll('.guided-nav button')[3].click();$('comparisonStage2').prepend(skip);$('comparisonStage2').querySelector('h3').textContent='3. Benefits · optional';
})();
